8	import lombok.extern.slf4j.Slf4j;
9	import org.springframework.beans.factory.annotation.Value;
10	import org.springframework.stereotype.Component;
11	
12	import javax.annotation.PostConstruct;
13	import javax.annotation.Resource;
14	
15	
16	@Component
17	@Slf4j
18	public class Producers {
19	
20		@Resource
21		private EventDrivenPublisher eventDrivenPublisher;
22	
23		@Value("${kafka.config.common-queue-02.producer.properties.indicator-change.topic:workbench_indicator_change}")
24		private String topic;
25	
26		@Value("${kafka.topic.fullfill_node_change:fulfill_node_change}")
27		private String fullFillNodeChangeTopic;
28	
29		@Value("${kafka.topic.schedule_data_recovery:schedule_data_recovery}")
30		private String scheduleTopic;
31	
32		@PostConstruct
33		public void init() {
34			EventDrivenPublisher.registerType(new String[]{MessageBizTypeConst.INDICATOR_CHANGED}, new KafkaMessageRoute(topic));
35			EventDrivenPublisher.registerType(new String[]{MessageBizTypeConst.FULFILL_NODE_CHANGE}, new KafkaMessageRoute(fullFillNodeChangeTopic));
36			EventDrivenPublisher.registerType(new String[]{MessageBizTypeConst.SCHEDULE_ASSESSMENT, MessageBizTypeConst.SCHEDULE_TASK}, new KafkaMessageRoute(scheduleTopic));
37		}
38	
39		public <T> void send(PayLoadData<T> payLoadData) {
40			if (payLoadData == null) {
41				return;
42			}
43			LOGGER.info("==>>>发送消息，待发送的消息：payload = {}", JsonUtils.obj2JsonStr(payLoadData));
44			try {
45				this.eventDrivenPublisher.persistPublishMessage(payLoadData.getData(), payLoadData.getBizType(), payLoadData.getContextKey());
46			} catch (Exception e) {
47				LOGGER.error("==>>>发送消息失败", e);
48			}
49		}
50	
51	}
