142		@Override
143	    public void handleBiz(OfcFulfillmentNodePayload payloadData, String eventContextKey) {
144	
145			// 如果如果没有订单信息生成 订单信息
146			LOGGER.info("OfcFulfillmentEventHandler payloadData[{}] eventContextKey[{}]", payloadData, eventContextKey);
147	
148			// 监听主材任务节点
149			if (DispatchReceiptTypeEnum.RECEIPT_TASK.getCode().equals(payloadData.getReceiptType())) {
150				if (payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.SELF_DESIGN_NOTIFY.getCode())
151						|| payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.SELF_RECHECK_FINISH.getCode())
152						|| payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.SELF_RECHECK_NOTIFY.getCode())
153						|| payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.DESIGN_OR_DESIGN_REVIEW_FINISHED.getCode())) {
154					LOGGER.info("OfcFulfillmentEventHandler获取主材考核数据, id:{}", payloadData.getReceiptNo());
155	
156					// 通知复尺, 复尺完成, 设计, 报价变更
157					// 从主材任务获取projectOrderId, categoryId, deliveryId
158					TaskDispatchDetailSimpleParam param = new TaskDispatchDetailSimpleParam();
159					param.setTaskDispatchId(Long.valueOf(payloadData.getReceiptNo()));
160					List<TaskDispatchDetailSimpleDTO> tasks;
161					try {
162						tasks = edarStarlordRpc.taskDetail(param);
163					} catch (Exception e) {
164						LOGGER.error("OfcFulfillmentEventHandler获取主材考核数据失败, id:{}", payloadData.getReceiptNo());
165						throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取主材任务失败", e);
166					}
167					if (tasks != null && !tasks.isEmpty()) {
168						TaskDispatchDetailSimpleDTO task = tasks.get(0);
169						String projectOrderId = String.valueOf(task.getProjectOrderId());
170						String categoryId = task.getMaterialCode();
171	
172						if (noMatchRule(categoryId, null, null, null)) {
173							LOGGER.info("未查询到满足的考核规则, 无需计算");
174							return;
175						}
176	
177						// 只有依赖用工条件的旧考核, 才会走这里
178						// 依赖用工的新考核, 在监听主材任务消息的位置处理
179						Boolean isInScheduleConfig;
180						try {
181							isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(projectOrderId);
182						} catch (Exception e) {
183							LOGGER.info("OfcFulfillmentEventHandler获取排程配置开关失败, projectOrderId:{}, err:", projectOrderId, e);
184							throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取配置开关失败", e);
185						}
186	
187						if (!isInScheduleConfig) {
188							FigureParam figureParam = indicatorDAGService.transEventNodeByOrder(null, projectOrderId, categoryId, payloadData.getActionType());
189							if (figureParam == null) {
190								LOGGER.info("未查询到需要计算的事件节点");
191								return;
192							}
193							LOGGER.info("doExecute开始计算ofc节点信息, projectId:{}, startNode: {}, extNode: {}",
194									figureParam.getProjectOrderNo(),
195									figureParam.getStartNodes().stream().map(EventNode::getCode).collect(Collectors.toList()),
196									figureParam.getExtNodes().stream().map(EventNode::getCode).collect(Collectors.joining(","))
197							);
198							evalOrderService.calculateIndicatorByEvents(figureParam.getProjectOrderNo(), figureParam.getStartNodes(), figureParam.getExtNodes());
199						}
200					}
201	            }
202			}
203	
204			// 其余支持的场景
205			if (OTHER_SCENE.contains(payloadData.getReceiptType())) {
206	
207				SubOrderComplexDto subOrderComplexDto;
208				try {
209					subOrderComplexDto = omsRpc.queryBaseByOrderNo(payloadData.getFlowMainNo());
210				} catch (RpcException e) {
211					LOGGER.error("OfcFulfillmentEventHandler获取货单信息失败，payloadData:{}, err:", JsonUtil.obj2JsonStr(payloadData), e);
212					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "查询销售单信息异常", e);
213				}
214	
215				if (subOrderComplexDto == null || subOrderComplexDto.getProjectOrderId() == null) {
216					LOGGER.info("未查询到subOrderComplexDto信息，payloadData:{}，flowMainNo:{}", JsonUtil.obj2JsonStr(payloadData), payloadData.getFlowMainNo());
217					return;
218				}
219	
220				Boolean isInSchedule;
221				try {
222					isInSchedule = edarStarlordRpc.queryProjectInScheduleSwitch(String.valueOf(subOrderComplexDto.getProjectOrderId()));
223				} catch (Exception e) {
224					LOGGER.error("OfcFulfillmentEventHandler获取排程配置开关失败, projectOrderId:{}, err:", subOrderComplexDto.getProjectOrderId(), e);
225					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取配置开关失败", e);
226				}
227	
228				// 完成已激活的通知送货任务
229				if (payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.UPDATE_EXPECT_ARRIVED_TIME.getCode())
230						|| payloadData.getActionType().equals(DispatchReceiveActionTypeEnum.OMS_NOTIFY_READY_TO_ENTER.getCode())) {
231					fulfillmentExecutor.execute(() -> {
232						FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
233						fulfillmentTaskExample.createCriteria()
234								.andRelateSubOrderNoEqualTo(payloadData.getReceiptNo())
235								.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode())
236								.andStatusIn(Arrays.asList(
237										FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode(),
238										FulfillmentTaskStatusEnum.FINISHED.getTypeCode()))
239								.andIsDeleteEqualTo((byte) 0);
240	
241						Long operatorId = null;
242						if (StringUtils.isNotEmpty(payloadData.getOperatorId()) && NumberUtil.isLong(payloadData.getOperatorId())) {
243							operatorId = Long.valueOf(payloadData.getOperatorId());
244						}
245	
246						TaskOperationContext context = new TaskOperationContext();
247						context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
248						context.setOperatorId(operatorId);
249						context.setNoticeRetainTime(subOrderComplexDto.getExpectArrivedTime());
250						context.setOperatorName(payloadData.getOperator());
251						fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
252					});
253	
254					// 未切排程的欧索的通知送货, 要特殊处理
255					boolean ouSuo = subOrderComplexDto.getSyncSystem() != null
256							&& subOrderComplexDto.getSyncSystem() == SyncSystemEnum.OPEN_PLATFORM.getCode();
257					if (ouSuo && !isInSchedule) {
258						syncMaterialTaskService.ouSuoNoticeDeliveryHandle(payloadData.getFlowMainNo());
259					}
260				}
261	
262				// 返补相关任务处理
263				doReplenishTask(payloadData, subOrderComplexDto);
264				if (NOT_DEAL_TASK.contains(payloadData.getActionType())) {
265					// 跟单员工作台确认 不再进行后续处理
266					return;
267				}
268	
269				// 生成接单、备货、进仓、报价、报价验收 任务
270	            try {
271	                doExecuteGenerateTask(payloadData, subOrderComplexDto, isInSchedule);
272	            } catch (RpcException e) {
273					LOGGER.error("doExecuteGenerateTask生成主材任务异常, e:", e);
274	            }
275	
276	            // task 任务更新
277				doExecuteModifyTask(payloadData, subOrderComplexDto);
278	
279				// 工作台自身时效信息保存和更新
280				// 主材任务用工节点上边已经计算过了, 这里不需要再计算
281				// 这里不计算来自主材任务的SO消息，否则会死循环
282				if (DispatchReceiptTypeEnum.RECEIPT_SO.getCode().equals(payloadData.getReceiptType())
283						&& "TASK".equals(payloadData.getSourceSystem())) {
284					return;
285				}
286				indicatorCalcExecutor.execute(() -> {
287					doExecute(payloadData.getFlowMainNo(), payloadData, isInSchedule);
288				});
289			}
290		}
