436		private void doExecuteModifyTask(OfcFulfillmentNodePayload payloadData, SubOrderComplexDto subOrderComplexDto) {
437			if (subOrderComplexDto == null) {
438				return;
439			}
440	
441			if (DispatchReceiveActionTypeEnum.SDM_NOTIFY_RECEIVE.getCode().equals(payloadData.getActionType())) {
442				// 完成接单任务
443				updateFulfillmentTaskByActionType(payloadData, FulfillmentTaskTypeEnum.TAKE_ORDER, FulfillmentTaskStatusEnum.FINISHED);
444			}
445	
446			// 仓库配送的接单
447			if (DeliveryTypeEnum.WAREHOUSE.getType().equals(subOrderComplexDto.getDeliveryType())
448					&& DispatchReceiveActionTypeEnum.WMS_NOTIFY_RECEIVE.getCode().equals(payloadData.getActionType())) {
449				// 完成接单任务
450				updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.TAKE_ORDER, FulfillmentTaskStatusEnum.FINISHED);
451			}
452	
453			if (DispatchReceiveActionTypeEnum.SDM_NOTIFY_STOCK_UP_FINISH.getCode().equals(payloadData.getActionType())){
454				// 完成备货任务
455				updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.STOCKING, FulfillmentTaskStatusEnum.FINISHED);
456			}
457	
458			if (DispatchReceiveActionTypeEnum.WMS_NOTIFY_RECEIPT_COMPLETE.getCode().equals(payloadData.getActionType())){
459				// 完成仓库收货任务
460				updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.STOCK_IN, FulfillmentTaskStatusEnum.FINISHED);
461			}
462	
463			// 提交测量报价
464			if (DispatchReceiveActionTypeEnum.SDM_NOTIFY_MEASUREMENT_QUOTATION.getCode().equals(payloadData.getActionType())) {
465				// 更新测量报价任务, 2024-05-22 问了小美产品后，只同步第一次提交测量报价和最终的审核通过，后续提交测量报价忽略
466				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
467				fulfillmentTaskExample.createCriteria()
468						.andRelateSubOrderNoEqualTo(payloadData.getFlowMainNo())
469						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.QUOTATION_TASK.getTypeCode())
470						.andStatusEqualTo(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())
471						.andIsDeleteEqualTo((byte) 0);
472				List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
473				if (CollectionUtils.isEmpty(fulfillmentTasks)) {
474					updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.QUOTATION_TASK, FulfillmentTaskStatusEnum.FINISHED);
475				} else {
476					LOGGER.info("测量报价任务存在已完成的，忽略此次测量报价提交通知，订单号:{}", payloadData.getFlowMainNo());
477				}
478	
479				// 提交测量报价后更新或者重新创建 测量报价待审核任务
480				FulfillmentTaskExample quotationTaskExample = new FulfillmentTaskExample();
481				quotationTaskExample.createCriteria()
482					.andRelateSubOrderNoEqualTo(payloadData.getFlowMainNo())
483					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.AUX_QUOTATION_ACCEPTANCE_TASK.getTypeCode());
484	
485				FulfillmentTask quotationTask = fulfillmentTaskMapper.selectOneByExample(quotationTaskExample);
486	
487				if (!subOrderComplexDto.getSecondType().equals(SecondType.AUXILIARY.getSecondType())) {
488					return;
489				}
490				if (quotationTask == null) {
491					FulfillmentTaskCreateParam fulfillmentTaskCreateParam = fulfillmentTaskWriteService.initFulfillmentTaskParam(
492							payloadData.getFlowMainNo(), payloadData.getFlowMainNo(), subOrderComplexDto, com.ke.utopia.enumeration.RoleTypeEnum.FOREMAN.getCode()
493					);
494					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.AUX_QUOTATION_ACCEPTANCE_TASK.getTypeCode());
495					fulfillmentTaskCreateParam.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
496					FulfillmentTask fulfillmentTask = fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
497					LOGGER.info("【{}】生成成功, fulfillmentTask:{}", FulfillmentTaskTypeEnum.getTaskTypeDescByType(FulfillmentTaskTypeEnum.AUX_QUOTATION_ACCEPTANCE_TASK.getTypeCode()), JsonUtil.obj2JsonStr(fulfillmentTask));
498				} else if (!FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode().equals(quotationTask.getStatus())) {
499					Long operatorId = null;
500					if (StringUtils.isNotEmpty(payloadData.getOperatorId()) && NumberUtil.isLong(payloadData.getOperatorId())) {
501						operatorId = Long.valueOf(payloadData.getOperatorId());
502					}
503					TaskOperationContext context = new TaskOperationContext();
504					context.setTargetStatusEnum(FulfillmentTaskStatusEnum.ACTIVATED);
505					context.setOperatorId(operatorId);
506					context.setOperatorName(payloadData.getOperator());
507					fulfillmentTaskWriteService.updateTask(quotationTaskExample,context);
508				}
509			}
510	
511			// 测量报价通过
512			if (DispatchReceiveActionTypeEnum.OMS_NOTIFY_MEASUREMENT_QUOTATION_PASS.getCode().equals(payloadData.getActionType())) {
513				// 更新测量报价任务
514				updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK, FulfillmentTaskStatusEnum.FINISHED);
515				updateFulfillmentTaskByActionType(payloadData,FulfillmentTaskTypeEnum.AUX_QUOTATION_ACCEPTANCE_TASK, FulfillmentTaskStatusEnum.FINISHED);
516			}
517		}
