519		private void doExecuteGenerateTask(OfcFulfillmentNodePayload payloadData, SubOrderComplexDto subOrderComplexDto, Boolean isInSchedule) throws RpcException {
520			if (subOrderComplexDto == null) {
521				return;
522			}
523	
524			// 校验是否需要生成任务
525			boolean needGenerateFulfillmentTask = needGenerateFulfillmentTask(subOrderComplexDto, isInSchedule);
526	
527			// 不需要生成，直接返回
528			if (!needGenerateFulfillmentTask) {
529				LOGGER.info("【接单/备货/进仓】订单：{},不需要生成任务", subOrderComplexDto.getOrderNo());
530				return;
531			}
532	
533			// 获取需要生成的任务类型
534			List<Integer> needGenerateTaskTypeList = getGenerateTaskTypeList(subOrderComplexDto);
535	
536			// 需要测量的订单 生成报价任务
537			if (subOrderComplexDto.getNeedMeasure() != null && subOrderComplexDto.getNeedMeasure().equals(YnEnum.YES.getCode())) {
538				// 生成报价任务
539				List<Integer> taskTypeList = new ArrayList<>(Arrays.asList(
540						FulfillmentTaskTypeEnum.QUOTATION_TASK.getTypeCode(),
541						FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK.getTypeCode()
542				));
543				for (Integer taskType : taskTypeList){
544					FulfillmentTaskExample example = new FulfillmentTaskExample();
545					example.createCriteria()
546							.andIsDeleteEqualTo((byte) 0)
547							.andReceiptNoEqualTo(subOrderComplexDto.getOrderNo())
548							.andTaskTypeEqualTo(taskType);
549					List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(example);
550					if (CollectionUtils.isEmpty(fulfillmentTasks)) {
551						this.handleCreateTask(payloadData, subOrderComplexDto, taskType);
552					}
553				}
554			}
555	
556			// 生成其他任务, 接单/备货/进仓
557			for (Integer taskType : needGenerateTaskTypeList) {
558				FulfillmentTaskExample example = new FulfillmentTaskExample();
559				example.createCriteria()
560						.andIsDeleteEqualTo((byte) 0)
561						.andReceiptNoEqualTo(subOrderComplexDto.getOrderNo())
562						.andTaskTypeEqualTo(taskType);
563				List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(example);
564				if (CollectionUtils.isEmpty(fulfillmentTasks)) {
565					this.handleCreateTask(payloadData, subOrderComplexDto, taskType);
566				}
567			}
568		}
