649		public void handleCreateTask(OfcFulfillmentNodePayload payloadData, SubOrderComplexDto subOrderComplexDto, Integer taskType) {
650			String roleType = RoleTypeEnum.SUPPLIER.getCode();
651			if (DeliveryTypeEnum.WAREHOUSE.getType().equals(subOrderComplexDto.getDeliveryType())) {
652				roleType = com.ke.utopia.enumeration.RoleTypeEnum.STOCK_MAN.getCode();
653			}
654			if (FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK.getTypeCode().equals(taskType)) {
655				roleType = com.ke.utopia.enumeration.RoleTypeEnum.FOREMAN.getCode();
656			}
657	
658			FulfillmentTaskCreateParam fulfillmentTaskCreateParam = fulfillmentTaskWriteService.initFulfillmentTaskParam(
659					payloadData.getFlowMainNo(), payloadData.getFlowMainNo(), subOrderComplexDto, roleType
660			);
661			fulfillmentTaskCreateParam.setFulfillmentTaskType(taskType);
662			FulfillmentTask fulfillmentTask = fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
663			LOGGER.info("【{}】生成成功, fulfillmentTask:{}", FulfillmentTaskTypeEnum.getTaskTypeDescByType(taskType), JsonUtil.obj2JsonStr(fulfillmentTask));
664		}
