720		public void doExecute(String flowMainNo, OfcFulfillmentNodePayload payloadData, Boolean isInSchedule) {
721			Transaction transaction = Cat.newTransaction("ofcNodeInfoCalculate", "doExecute");
722			try {
723				transaction.addData("orderNo=" + flowMainNo + "&actionType=" + payloadData.getActionType());
724				IndicatorOrderBO orderBo = indicatorOrderService.buildOrderBo(flowMainNo, payloadData);
725	
726				// 排程初始化数据白名单
727				Boolean scheduleInit = indicatorScheduleDAGService.isScheduleProject(orderBo.getProjectOrderId());
728	
729				if (isInSchedule || scheduleInit) {
730					// 排程新配置考核, 或者排程数据白名单
731					FigureScheduleParam scheduleParam = indicatorScheduleDAGService.transEventNodeByOrder(flowMainNo, null, null, payloadData.getActionType());
732					if (scheduleParam != null) {
733						LOGGER.info("doExecute开始计算ofc节点信息, projectId:{}, startNode: {}",
734								scheduleParam.getProjectOrderId(),
735								scheduleParam.getStartNodes().stream().map(ScheduleEventNode::getUniqCode).collect(Collectors.toList()));
736						// 按照新配置计算考核, isInScheduleConfig情况下数据同步给主材任务
737						evalScheduleOrderService.calculateScheduleIndicatorByEvents(scheduleParam.getProjectOrderId(), scheduleParam.getStartNodes(), scheduleParam.getExtNodes(), isInSchedule);
738						transaction.setStatus(Transaction.SUCCESS);
739					}
740				}
741				if (!isInSchedule) {
742					// 未命中新排程配置, 使用旧考核
743					if (noMatchRule(orderBo.getCategoryId(), orderBo.getBusinessType(), orderBo.getSecondType(), orderBo.getBusinessVersion())) {
744						LOGGER.info("未查询到满足的考核规则, 无需计算");
745						transaction.setStatus(Transaction.SUCCESS);
746						return;
747					}
748					FigureParam figureParam = indicatorDAGService.transEventNodeByOrder(flowMainNo, null, null, payloadData.getActionType());
749					if (figureParam == null) {
750						LOGGER.info("未查询到需要计算的事件节点");
751						transaction.setStatus(Transaction.SUCCESS);
752						return;
753					}
754					LOGGER.info("doExecute开始计算ofc节点信息, projectId:{}, startNode: {}, extNode: {}",
755							figureParam.getProjectOrderNo(),
756							figureParam.getStartNodes().stream().map(EventNode::getCode).collect(Collectors.toList()),
757							figureParam.getExtNodes().stream().map(EventNode::getCode).collect(Collectors.joining(","))
758					);
759					evalOrderService.calculateIndicatorByEvents(figureParam.getProjectOrderNo(), figureParam.getStartNodes(), figureParam.getExtNodes());
760				}
761				transaction.setStatus(Transaction.SUCCESS);
762			} catch (OrderBuildException obe) {
763				transaction.setStatus(obe);
764				LOGGER.info("OrderBuildException, flowMainNo: {}, payloadData: {}, err: ", flowMainNo, JsonUtil.obj2JsonStr(payloadData), obe);
765			} catch (Exception e) {
766				transaction.setStatus(e);
767				LOGGER.info("消费ofc节点信息计算失败 payload :{}, doExecute error", JsonUtil.obj2JsonStr(payloadData), e);
768			} finally {
769				transaction.complete();
770			}
771		}
772	
773		private boolean noMatchRule(String categoryId, Integer businessType, Integer secondType, String businessVersion) {
774			IndicatorComputeRuleExample example = new IndicatorComputeRuleExample();
775			IndicatorComputeRuleExample.Criteria criteria = example.createCriteria();
776			criteria.andCategoryIdEqualTo(categoryId);
777			if (businessType != null) {
778				criteria.andBusinessTypeEqualTo(businessType);
779			}
780			if (secondType != null) {
781				criteria.andSecondTypeEqualTo(secondType);
782			}
783			if (businessVersion != null) {
784				criteria.andBusinessVersionEqualTo(businessVersion);
785			}
786			return indicatorComputeRuleMapper.selectOneByExample(example) == null;
787		}
