104		public void handleBiz(OmsSubOrderEventPayLoad payloadData, String eventContextKey) {
105			LOGGER.info("OmsSubOrderEventHandler payloadData[{}] eventContextKey[{}]", JsonUtils.obj2JsonStr(payloadData), eventContextKey);
106			if (payloadData != null) {
107	
108				indicatorOrderService.updateOrderStatus(payloadData);
109	
110				SubOrderComplexDto subOrderComplexDto = omsRpc.queryBaseByOrderNo(payloadData.getOrderNo());
111				if (subOrderComplexDto == null || subOrderComplexDto.getProjectOrderId() == null) {
112					LOGGER.info("未查询到subOrderComplexDto信息，payloadData:{}，flowMainNo:{}", JsonUtil.obj2JsonStr(payloadData), payloadData.getOrderNo());
113					return;
114				}
115	
116				dealPlaceOrderTask(payloadData, subOrderComplexDto);
117	
118				// 切换到排程配置的欧索, 放过
119				Boolean isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(String.valueOf(subOrderComplexDto.getProjectOrderId()));
120				boolean ouSuoSchedule = subOrderComplexDto.getSyncSystem() != null
121						&& subOrderComplexDto.getSyncSystem() == SyncSystemEnum.OPEN_PLATFORM.getCode()
122						&& isInScheduleConfig;
123	
124	
125				// 没有重构标记理论上不生成
126				boolean rebuild = GreyVersion.OMS_REFACTOR1_0.getVersion().equals(payloadData.getGreyVersion());
127	
128				// 1.0不处理
129				boolean isVersion1_0 = BusinessVersion.VERSION1_0.getVersion().equals(payloadData.getBusinessVersion());
130	
131				if ((!rebuild || isVersion1_0) && !ouSuoSchedule) {
132					return;
133				}
134	
135				if (SecondType.CENTRALIZED_PURCHASE.getSecondType() == payloadData.getSecondType()) {
136					return;
137				}
138	
139				// 因为开始支持辅材逻辑了,并非只是给主材任务的逻辑
140				doUpdateTask(payloadData, subOrderComplexDto);
141	
142				if (SecondType.MASTER.getSecondType() != payloadData.getSecondType()
143						&& SecondType.CENTRAL.getSecondType() != payloadData.getSecondType()
144						&& SecondType.INTEGRATE_RETAIL_ORDER.getSecondType() != payloadData.getSecondType()
145						&& SecondType.JINGZHUANG_QUANAN.getSecondType() != payloadData.getSecondType()
146						&& !(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(payloadData.getSecondType())
147								&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
148								&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode()))) {
149					return;
150				}
151	
152				// 未切排程的北京项目, 不处理
153				if (BusinessVersion.VERSION2_5.getVersion().equals(payloadData.getBusinessVersion())) {
154					FulfillmentSystemModeConfigDto fulfillmentSystemModeConfigDto = ofcRpc.queryServiceFlowTypeConfig(payloadData.getOrderNo());
155					if (fulfillmentSystemModeConfigDto != null
156							&& fulfillmentSystemModeConfigDto.getSystemMode().equals(FulfillmentSystemModeEnum.BEIWO.name())
157							&& !ouSuoSchedule
158							&& !isInScheduleConfig) {
159						return;
160					}
161				}
162	
163				// 处理通知类任务
164				doCreateOrActiveNotifyTask(payloadData);
165	
166				// 处理生成任务
167				// 送货、签收、设计任务、报价变更任务生成
168				doCreateGoodsTask(payloadData, subOrderComplexDto);
169			}
170		}
