172		private void dealPlaceOrderTask(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) throws RpcException {
173	
174			if (DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(payloadData.getSecondType())
175					&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
176					&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode())) {
177				if (payloadData.getEvent().equals(SubOrderEventEnum.GENERATE.getKey())
178						&& payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())) {
179					// 只处理返补货单的初始化消息
180					doReplenishTask(payloadData, subOrderComplexDto);
181				}
182				// 返补单不走后续流程
183				return;
184			}
185	
186			if (!payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())) {
187				return;
188			}
189	
190			// 完成下单任务
191			fulfillmentTaskWriteService.handleFinishPlaceOrderTask(payloadData, subOrderComplexDto);
192	
193			// 更新非灰度的 2.0下单任务
194			twoZeroPlaceOrderTaskBizService.updatePlaceOrderBySubEvent(payloadData, subOrderComplexDto);
195	
196			// 绑定报价变更单任务
197			rescaleTaskBizService.bindRelateSubOrderNo(payloadData, subOrderComplexDto);
198	
199		}
