219		private void doUpdateTask(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) throws RpcException {
220			if (payloadData.getEvent().equals(SubOrderEventEnum.PORTAGE_FEE_REJECT.getKey())
221					|| payloadData.getEvent().equals(SubOrderEventEnum.PORTAGE_FEE_PASSED.getKey())) {
222				// 搬楼费相关处理
223				portageDeal(payloadData);
224			} else if (Objects.equals(payloadData.getStatus(), SubOrderStateEnum.WAITING_SIGN.getValue())) {
225				// 待签收
226				transitFinish(payloadData);
227			} else if (Objects.equals(payloadData.getStatus(), SubOrderStateEnum.FINISHED.getValue())) {
228				// 完成
229				orderFinish(payloadData);
230			} else if (Objects.equals(payloadData.getStatus(), SubOrderStateEnum.SIGN_REJECTED.getValue())) {
231				// 拒签
232				signRejected(payloadData);
233			} else if (Objects.equals(payloadData.getStatus(), SubOrderStateEnum.CANCELED.getValue())
234					|| Objects.equals(payloadData.getStatus(),SubOrderStateEnum.REJECTED.getValue()))  {
235				// 取消, 拒单
236				orderCancel(payloadData, subOrderComplexDto);
237			} else if (SubOrderEventEnum.TRANSIT_FAILED.getKey().equals(payloadData.getEvent())) {
238				// 送达失败
239				transitFailed(payloadData);
240			} else if (SubOrderEventEnum.TRANSIT_FINISH.getKey().equals(payloadData.getEvent())) {
241				// 送达成功
242				transitFinish(payloadData);
243			}
244		}
