246		private void portageDeal(OmsSubOrderEventPayLoad payloadData) {
247			// 搬楼费比较特殊, 先处理
248			FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
249			fulfillmentTaskExample.createCriteria()
250					.andRelateSubOrderNoEqualTo(payloadData.getOrderNo())
251					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PORTAGE_AUDIT.getTypeCode())
252					.andStatusNotEqualTo(FulfillmentTaskStatusEnum.CANCELED.getTypeCode());
253	
254			TaskOperationContext context = new TaskOperationContext();
255			context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
256			context.setOperatorId(StringUtils.isNotBlank(payloadData.getOperatorUcId()) && NumberUtil.isLong(payloadData.getOperatorUcId()) ?
257					Long.valueOf(payloadData.getOperatorUcId()) : null);
258			context.setOperatorName(payloadData.getOperator());
259			context.setExtInfo("");
260			if (payloadData.getEvent().equals(SubOrderEventEnum.PORTAGE_FEE_REJECT.getKey())) {
261				Map<String, String> extra = new HashMap<>();
262				extra.put("desc", "已驳回");
263				context.setExtInfo(JsonUtil.obj2JsonStr(extra));
264			}
265			fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
266		}
