268		private void signRejected(OmsSubOrderEventPayLoad payloadData) {
269			// 主材签收任务要设置成已完成(拒签), 然后新建一个待激活的签收任务
270			FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
271			fulfillmentTaskExample.createCriteria()
272					.andRelateSubOrderNoEqualTo(payloadData.getOrderNo())
273					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode())
274					.andStatusIn(Arrays.asList(
275							FulfillmentTaskStatusEnum.GENERATED.getTypeCode(),
276							FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode()))
277					.andIsDeleteEqualTo((byte) 0);
278	
279			Map<String, String> extra = new HashMap<>();
280			extra.put("desc", "已拒签");
281			FulfillmentTask target = FulfillmentTask.builder()
282					.status(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())
283					.ucid(StringUtils.isNotBlank(payloadData.getOperatorUcId()) && NumberUtil.isLong(payloadData.getOperatorUcId()) ?
284							Long.valueOf(payloadData.getOperatorUcId()) : null)
285					.finishTime(new Date())
286					.extInfo(JsonUtil.obj2JsonStr(extra))
287					.build();
288	
289			// 不使用fulfillmentTaskWriteService.updateTask是防止同步给主材任务
290			List<FulfillmentTask> tasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
291			List<Long> ids = new ArrayList<>();
292			if (!tasks.isEmpty()) {
293				fulfillmentTaskMapper.updateByExampleSelective(target, fulfillmentTaskExample);
294				// 重新生成主材签收任务
295				FulfillmentTask newTask = tasks.get(0);
296				newTask.setId(null);
297				newTask.setReceiptNo(null);
298				newTask.setActiveTime(null);
299				newTask.setAssessmentTime(null);
300				newTask.setFinishTime(null);
301				newTask.setCancelTime(null);
302				fulfillmentTaskMapper.insertSelective(newTask);
303				ids.add(newTask.getId());
304			}
305	
306			// 辅材签收任务, 直接原地重启
307			// 主材签收任务, 在新生成的签收任务上重启
308			fulfillmentTaskExample.clear();
309			fulfillmentTaskExample.createCriteria()
310					.andRelateSubOrderNoEqualTo(payloadData.getOrderNo())
311					.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.AUX_READY_TO_SIGN.getTypeCode())
312					.andIsDeleteEqualTo((byte) 0);
313			List<FulfillmentTask> auxTasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
314			ids.addAll(auxTasks.stream()
315					.map(FulfillmentTask::getId)
316					.collect(Collectors.toList()));
317	
318			// 更新并同步主材任务
319			fulfillmentTaskExample.clear();
320			if (!ids.isEmpty()) {
321				fulfillmentTaskExample.createCriteria()
322						.andIdIn(ids);
323				TaskOperationContext context = new TaskOperationContext();
324				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.GENERATED);
325				context.setOperatorId(StringUtils.isNotBlank(payloadData.getOperatorUcId()) && NumberUtil.isLong(payloadData.getOperatorUcId()) ?
326						Long.valueOf(payloadData.getOperatorUcId()) : null);
327				context.setOperatorName(payloadData.getOperator());
328				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
329			}
330		}
