332		private void orderCancel(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) throws RpcException {
333			List<Integer> taskTypeList = new ArrayList<>(Arrays.asList(
334					FulfillmentTaskTypeEnum.PORTAGE_AUDIT.getTypeCode(),
335					FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode(),
336					FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode(),
337					FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode(),
338					FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY_BATCH.getTypeCode(),
339					FulfillmentTaskTypeEnum.TAKE_ORDER.getTypeCode(),
340					FulfillmentTaskTypeEnum.STOCKING.getTypeCode(),
341					FulfillmentTaskTypeEnum.STOCK_IN.getTypeCode(),
342					FulfillmentTaskTypeEnum.QUOTATION_TASK.getTypeCode(),
343					FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK.getTypeCode(),
344					FulfillmentTaskTypeEnum.DESIGN_SERVICE.getTypeCode(),
345					FulfillmentTaskTypeEnum.DESIGN_READY_TO_SIGN.getTypeCode(),
346					FulfillmentTaskTypeEnum.AUX_QUOTATION_ACCEPTANCE_TASK.getTypeCode(),
347					FulfillmentTaskTypeEnum.AUX_READY_TO_SIGN.getTypeCode(),
348					FulfillmentTaskTypeEnum.PRE_INSTALL_READY_TO_SIGN.getTypeCode(),
349					FulfillmentTaskTypeEnum.PRE_INSTALL_GET_READY_TO_DELIVERY.getTypeCode(),
350					FulfillmentTaskTypeEnum.INSTALL_GET_READY_TO_DELIVERY.getTypeCode(),
351					FulfillmentTaskTypeEnum.INSTALL_READY_TO_SIGN.getTypeCode(),
352					FulfillmentTaskTypeEnum.DESIGN_REVIEW.getTypeCode()
353			));
354	
355			boolean replenish = DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(payloadData.getSecondType())
356					&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
357					&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode());
358			if (replenish) {
359				taskTypeList.addAll(Arrays.asList(
360						FulfillmentTaskTypeEnum.REPORT_PROBLEM.getTypeCode(),
361						FulfillmentTaskTypeEnum.DESIGNER_CONFIRM.getTypeCode(),
362						FulfillmentTaskTypeEnum.SSC_APPROVE.getTypeCode(),
