455		private void doCreateGoodsTask(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) throws RpcException {
456	
457			// 项目是否切换到排程配置
458			Boolean scheduleSwitch = edarStarlordRpc.queryProjectInScheduleSwitch(String.valueOf(payloadData.getProjectOrderId()));
459	
460			// 处理 1.非排程货单 2.设计服务单 3.报价变更服务单
461			if (payloadData.getEvent().equals(SubOrderEventEnum.GENERATE.getKey())
462					&& ((payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode()) && !scheduleSwitch)
463							|| payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DESIGN.getCode())
464							|| payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.QUOTATION_REVIEW.getCode()))) {
465				handleCreateMaterialTask(payloadData, subOrderComplexDto);
466			}
467	
468			// 查看是否需要生成签收任务
469			SignForTaskConfDto sign = null;
470			if (!scheduleSwitch) {
471				sign = ofcRpc.querySignForTaskConf(payloadData.getOrderNo());
472				if (sign.getCanCreate() == null || !sign.getCanCreate()) {
473					return;
474				}
475			}
476	
477			if (scheduleSwitch) {
478				boolean needSign = fulfillmentTaskWriteService.needScheduleTask(payloadData.getOrderNo(), FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode());
479				if (!needSign) {
480					return;
481				}
482			}
483	
484			// 签收任务挪到这里创建
485			FulfillmentTaskCreateParam signForParam = fulfillmentTaskWriteService.initFulfillmentTaskParam(payloadData.getOrderNo(), payloadData.getOrderNo(), subOrderComplexDto, RoleTypeEnum.FOREMAN.getCode());
486			signForParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode());
487			signForParam.setTaskMode(scheduleSwitch ? TaskModeEnum.SCHEDULE.getTaskMode() : TaskModeEnum.ORIGIN.getTaskMode());
488			if (sign != null) {
489				RoleTypeEnum roleTypeEnum = RoleTypeEnum.getByValue(sign.getRoleType());
490				signForParam.setRoleType(roleTypeEnum == null ? null : roleTypeEnum.getCode());
491			}
492	
493			if (payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())
494					&& SubOrderStateEnum.WAITING_SIGN.getValue().equals(subOrderComplexDto.getStatus())) {
495				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
496				fulfillmentTaskExample.createCriteria()
497						.andRelateSubOrderNoEqualTo(payloadData.getOrderNo())
498						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode())
499						.andStatusEqualTo(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())
500						.andReceiptNoEqualTo("");
501				FulfillmentTask target = FulfillmentTask.builder()
502						.receiptNo(signForParam.getReceiptOrderNo())
503						.build();
504				fulfillmentTaskMapper.updateByExampleSelective(target, fulfillmentTaskExample);
505	
506				// 创建任务(实际上可能是激活)
507				// 排程配置生成的新任务, 这里是兼容的, 会将签收任务激活
508				fulfillmentTaskWriteService.createTask(signForParam, false);
509			}
510	
511		}
