513		public void handleCreateMaterialTask(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) throws RpcException {
514			if (!payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())
515					&& !payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.QUOTATION_REVIEW.getCode())
516					&& !payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DESIGN.getCode())) {
517				return;
518			}
519	
520			// 恶心逻辑 如果是设计和报价变更单独进行处理
521			if (payloadData.getBusinessVersion().equals(BusinessVersion.VERSION2_5.getVersion())
522					&& (payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DESIGN.getCode())
523							|| payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.QUOTATION_REVIEW.getCode()))) {
524				// 全国用工切换开关, 切换了则不在这里处理
525				if (fulfillmentTaskWriteService.getMdmCodeMergeSwitch(subOrderComplexDto.getProjectOrderId().toString())) {
526					return;
527				}
528				FulfillmentTaskCreateParam fulfillmentTaskCreateParam = fulfillmentTaskWriteService.buildTaskWithServiceOrder(
529						payloadData.getOrderNo(), payloadData.getOrderNo(), null, null, false, payloadData.getFulfillmentLinkCode()
530				);
531				if (fulfillmentTaskCreateParam == null) {
532					return;
533				}
534				fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
535				return;
536			}
537			if (payloadData.getFulfillmentLinkCode().equals(FulfillmentLinkEnum.DELIVERY.getCode())) {
538				FulfillmentSystemModeConfigDto fulfillmentSystemModeConfigDto = ofcRpc.queryServiceFlowTypeConfig(payloadData.getOrderNo());
539	
540				FulfillmentTaskCreateParam fulfillmentTaskCreateParam = fulfillmentTaskWriteService.initFulfillmentTaskParam(payloadData.getOrderNo(), payloadData.getOrderNo(), subOrderComplexDto, RoleTypeEnum.FOREMAN.getCode());
541	
542				// 生成送货任务
543				fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode());
544				fulfillmentTaskCreateParam.setRoleType(RoleTypeEnum.FOREMAN.getCode());
545				fulfillmentTaskCreateParam.setSystemFlowCode(fulfillmentSystemModeConfigDto != null && fulfillmentSystemModeConfigDto.getSystemMode() != null ?
546						fulfillmentSystemModeConfigDto.getSystemMode() : "");
547	
548				// 这里查询一下有没有对应的 通知送货任务如果是已完成状态 那么需要将初始状态设置为 已激活
549				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
550				fulfillmentTaskExample.createCriteria().andRelateSubOrderNoEqualTo(payloadData.getOrderNo())
551						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode())
552						.andStatusEqualTo(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())
553						.andIsDeleteEqualTo((byte)0);
554	
555				List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
556				if (CollectionUtils.isNotEmpty(fulfillmentTasks)) {
557					fulfillmentTaskCreateParam.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
558				}
559				fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
560			}
561		}
