584		public void doReplenishTask(OmsSubOrderEventPayLoad payloadData, SubOrderComplexDto subOrderComplexDto) {
585			// 返补下单任务
586			// 生成问题提报，上传图纸，下单，推单
587			// 2026-01-08 新返补流程, 对于定制品类会新增 定制设计师确认，设计SSC审核
588			String replenishOrderNo = payloadData.getOrderNo();
589	
590			// 是否新流程开城
591			boolean isNewProcess;
592	        try {
593	            SolutionOpenCityConfigDTO cityConfigDTO = artisanWorkOrderRpc.isNewReplenishmentProcess(subOrderComplexDto.getProjectOrderId().toString());
594				isNewProcess = cityConfigDTO.getIsOpenCity()
595						&& cityConfigDTO.getCategoryCodeList() != null
596						&& cityConfigDTO.getCategoryCodeList().contains(subOrderComplexDto.getSplitFrontCategoryId());
597	        } catch (RpcException e) {
598				LOGGER.error("获取返补单开城信息失败，projectOrderId:{}, err:", subOrderComplexDto.getProjectOrderId().toString(), e);
599				throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取返补单开城信息失败", e);
600			}
601	
602	        // 获取返补单拆单信息
603			SubOrderInfoDto replenishInfo;
604			try {
605				List<SubOrderInfoDto> subOrderInfoDtos = omsRpc.querySubOrderInfos(SubInfoQueryParam.builder()
606						.subOrderNos(Collections.singletonList(replenishOrderNo))
607						.withItem(true)
608						.build());
609				replenishInfo = subOrderInfoDtos.get(0);
610			} catch (RpcException e) {
611				LOGGER.error("获取返补单拆单信息失败,未查询到返补单信息，payloadData:{}, err:", JsonUtil.obj2JsonStr(payloadData), e);
612				throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取返补单拆单信息失败", e);
613			}
614	
615			if (DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(replenishInfo.getSecondType())) {
616				LOGGER.info("确认返补信息 - 开始初始化相关主材任务，replenishOrderNo:{}", replenishOrderNo);
617	
618				Boolean needUploadDrawing;
619				try {
620					NeedDrawingConfigDto needDrawingDto = ofcRpc.queryNeedDrawingConfig(QueryNeedDrawingConfigParam.builder()
621							.categoryId(replenishInfo.getSplitFrontCategoryId())
622							.supplierId(StringUtils.isNotEmpty(replenishInfo.getSupplierId()) ? replenishInfo.getSupplierId() : replenishInfo.getDeliveryId())
623							.branchCompanyCode(replenishInfo.getMdmCode())
624							.build());
625					needUploadDrawing = needDrawingDto.getNeedDrawing();
626				} catch (RpcException e) {
627					LOGGER.error("获取图纸上传信息失败,payloadData:{}, err:", JsonUtil.obj2JsonStr(payloadData), e);
628					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取图纸上传信息失败", e);
629				}
630	
631				// 从work-order获取返补单提报相关信息
632				List<IssueOrderExternalInfoDTO> workOrderInfos;
633				try {
634					List<String> workOrderNos = replenishInfo.getItems().stream()
635							.map(PlainOrderItemDto::getQuestionOrderNo)
636							.collect(Collectors.toList());
637					workOrderInfos = artisanWorkOrderRpc.batchDetailsByOrderNos(workOrderNos);
638				} catch (RpcException e) {
639					LOGGER.error("获取返补单提报信息失败,未查询到补单提报信信息，payloadData:{}, err:", JsonUtil.obj2JsonStr(payloadData), e);
640					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取返补单提报信息失败", e);
641				}
642				if (workOrderInfos == null || workOrderInfos.isEmpty()) {
643					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取返补单提报信息失败, 返回结果为空");
644				}
645	
646				// 初始化反补单相关的节点任务(问题提报，上传图纸，定制设计师确认，设计SSC审核，下单，推单)
647				initReplenishTask(replenishOrderNo, isNewProcess, replenishInfo, needUploadDrawing, workOrderInfos, subOrderComplexDto);
648			}
649		}
