651		public void initReplenishTask(String replenishOrderNo, Boolean isNewProcess, SubOrderInfoDto replenishInfo,
652									  Boolean needUploadDrawing, List<IssueOrderExternalInfoDTO> workOrderInfos,
653									  SubOrderComplexDto subOrderComplexDto) {
654			FulfillmentTaskCreateParam param;
655			// 是否一品多商
656			boolean multiSupplier = StringUtils.isNotEmpty(subOrderComplexDto.getTag()) && subOrderComplexDto.getTag().contains(OrderTagEnum.DELIVERY_PRE_ALLOCATE.getCode());
