688						param.setRoleType(UserTypeEnum.WOOD_DESIGNER.getDescription());
689						param.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
690						String operatorId = designerInfo.getHandlerInfo().getOperatorId();
691						if (StringUtils.isNotEmpty(operatorId)) {
692							param.setUcid(Long.valueOf(operatorId));
693						}
694						String name = designerInfo.getHandlerInfo().getOperatorName();
