704								.andProjectCodeEqualTo(subOrderComplexDto.getProjectCode())
705								.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.DESIGNER_CONFIRM.getTypeCode())
706								.andRelateSubOrderNoEqualTo(replenishOrderNo)
