766			// 创建图纸上传任务
767			// 不需要图纸上传则不创建
768			// 一品多商，创建时即为完成状态
769			// 非一品多商，创建为进行中
770			if (needUploadDrawing && !isNewProcess) {
771				param = fulfillmentTaskWriteService.initReplenishTaskParam(replenishOrderNo, replenishInfo, subOrderComplexDto);
772				param.setFulfillmentTaskType(FulfillmentTaskTypeEnum.UPLOAD_DRAWINGS.getTypeCode());
773				param.setReceiptOrderNo(replenishOrderNo);
774				param.setActiveTime(new Date());
775				param.setRoleType(UserTypeEnum.MATERIAL_SCHEDULING.getDescription());
776				if (multiSupplier) {
777					// 一品多商，创建时即为完成状态
778					List<DispatchReceiveDto> dispatchReceiveDtos = new ArrayList<>();
779					try {
780						dispatchReceiveDtos = ofcRpc.queryDispatchReceiveByMainFlowNo(replenishOrderNo);
781					} catch (Exception e) {
782						LOGGER.error("返补单拉取ofc轨迹异常, orderNo:{}, err:", replenishOrderNo, e);
783					}
784					DispatchReceiveDto updateDrawing = dispatchReceiveDtos.stream()
785							.filter(o -> o.getActionType().equals(DispatchReceiveActionTypeEnum.COE_PLATFORM_UPLOAD_DRAWING.getCode()))
786							.findFirst()
787							.orElse(null);
788	
789					param.setInitialStatus(FulfillmentTaskStatusEnum.FINISHED.getTypeCode());
790					param.setFinishTime(new Date());
791					if (updateDrawing != null) {
792						param.setUcid(StringUtils.isNotEmpty(updateDrawing.getOperatorId()) ? Long.parseLong(updateDrawing.getOperatorId()) : -1L);
793						param.setName(updateDrawing.getOperator());
794						param.setActiveTime(updateDrawing.getOperationTime());
795						param.setFinishTime(updateDrawing.getOperationTime());
796					}
797				} else {
798					param.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
799				}
800				fulfillmentTaskWriteService.createTask(param, false);
801			}
802	
803			// 创建下单任务
804			// 一品多商，创建时即为完成状态
805			// 非一品多商，创建为进行中
806			param = fulfillmentTaskWriteService.initReplenishTaskParam(replenishOrderNo, replenishInfo, subOrderComplexDto);
807			param.setFulfillmentTaskType(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode());
808			param.setReceiptOrderNo(replenishOrderNo);
809			param.setActiveTime(replenishInfo.getCreateTime());
810			param.setRoleType(UserTypeEnum.MATERIAL_SCHEDULING.getDescription());
811			param.setUcid(Long.parseLong(subOrderComplexDto.getUcid()));
812			param.setName(subOrderComplexDto.getCreator());
813			param.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
814			fulfillmentTaskWriteService.createTask(param, false);
815	
816			if (multiSupplier && !isNewProcess) {
817				// 一品多商要将下单任务完成
818				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
819				fulfillmentTaskExample.createCriteria()
820						.andProjectCodeEqualTo(subOrderComplexDto.getProjectCode())
821						.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
822						.andRelateSubOrderNoEqualTo(replenishOrderNo)
823						.andReplenishmentEqualTo(FlowTypeEnum.REVERSE_ORDER.getCode())
824						.andStatusEqualTo(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())
825						.andIsDeleteEqualTo((byte) 0);
826	
827				TaskOperationContext context = new TaskOperationContext();
828				context.setOperationTime(new Date());
829				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
830				context.setExecutingPartyNo(replenishOrderNo);
831				context.setReceiptNo(replenishOrderNo);
832				context.setRelateSubOrderNo(replenishOrderNo);
833	
834				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
835			}
836		}
