171			// 如果基于项目判断一下是不是2.0的项目
172			ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(Long.valueOf(payloadData.getProjectOrderId()));
173			if (projectOrderDto == null) {
174				return;
175			}
176			// 只处理2.0下单任务, 定制柜套内, 定制柜套外
177			if (BusinessModelEnum.SHENG_DU.getCode().equals(projectOrderDto.getBusinessModel())
178					&& apolloConfig.getSdRetailPlaceOrderCategoryIds().contains(payloadData.getMaterialCode())) {
179				try {
180					// 看看有没有下单任务
181					TaskDispatchDetailSimpleParam taskDispatchDetailSimpleParam = new TaskDispatchDetailSimpleParam();
182					taskDispatchDetailSimpleParam.setProjectOrderId(Long.valueOf(payloadData.getProjectOrderId()));
183					taskDispatchDetailSimpleParam.setTaskType(TaskTypeEnum.ORDER.getValue());
184					taskDispatchDetailSimpleParam.setMaterialCodes(Collections.singletonList(payloadData.getMaterialCode()));
185					taskDispatchDetailSimpleParam.setSupplierCodes(Collections.singletonList(payloadData.getSupplierCode()));
186	
187					List<TaskDispatchDetailSimpleDTO> taskDispatchDetailSimpleDTOS = edarStarlordRpc.taskDetail(taskDispatchDetailSimpleParam);
188					// 如果已经有下单任务, 就不再额外处理了
189					if (CollectionUtils.isNotEmpty(taskDispatchDetailSimpleDTOS)) {
190						return;
191					}
192	
193					// 获取复尺任务信息
194					TaskDispatchDetailSimpleParam recheckTask = new TaskDispatchDetailSimpleParam();
195					recheckTask.setProjectOrderId(Long.valueOf(payloadData.getProjectOrderId()));
196					recheckTask.setTaskType(TaskTypeEnum.RECHECK_SCALE.getValue());
197					recheckTask.setMaterialCodes(Collections.singletonList(payloadData.getMaterialCode()));
198					recheckTask.setSupplierCodes(Collections.singletonList(payloadData.getSupplierCode()));
199	
200					List<TaskDispatchDetailSimpleDTO> recheckTaskDto = edarStarlordRpc.taskDetail(recheckTask);
201					if (CollectionUtils.isEmpty(recheckTaskDto)) {
202						return;
203					}
204	
205					// 有复尺, 但是没有下单任务, 那就创建一个下单任务
206					TaskDispatchDetailSimpleDTO taskDispatchDetailSimpleDTO = recheckTaskDto.get(0);
207	
208					FulfillmentTaskCreateParam fulfillmentTaskCreateParam = new FulfillmentTaskCreateParam();
209					fulfillmentTaskCreateParam.setCategoryId(taskDispatchDetailSimpleDTO.getMaterialCode());
210					fulfillmentTaskCreateParam.setCategoryName(taskDispatchDetailSimpleDTO.getMaterialName());
211					fulfillmentTaskCreateParam.setSupplierCode(taskDispatchDetailSimpleDTO.getSupplierCode());
212					fulfillmentTaskCreateParam.setSupplierName(taskDispatchDetailSimpleDTO.getSupplierName());
213					fulfillmentTaskCreateParam.setProjectOrderId(String.valueOf(taskDispatchDetailSimpleDTO.getProjectOrderId()));
214					fulfillmentTaskCreateParam.setFulfillmentTaskType(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode());
215					fulfillmentTaskCreateParam.setReplenishment(FlowTypeEnum.NORMAL_ORDER.getCode());
216					fulfillmentTaskCreateParam.setActiveTime(new Date());
217					fulfillmentTaskCreateParam.setRoleType(RoleTypeEnum.WOOD_DESIGNER.getCode());
218					fulfillmentTaskCreateParam.setInitialStatus(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode());
219	
220					// 考核时间设置为 通知复尺预计完成时间 + 10天
221					TaskDispatchDetailSimpleDTO.TaskNodeDetail taskNodeDetail = taskDispatchDetailSimpleDTO.getTaskNodeDetailList().stream()
222							.filter(item -> item.getNodeType().equals(20))
223							.findAny().orElse(null);
224					if (taskNodeDetail != null) {
225						fulfillmentTaskCreateParam.setAssessmentTime(DateUtil.addDay(taskNodeDetail.getEstimatedTime(), 10));
226					}
227					fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
228				} catch (RpcException e) {
229					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取主材任务失败", e);
230				}
231			}
232		}
