234		private void figureScheduleData(MaterialTaskDispatchStateChangeMsgBO payloadData) {
235			String projectOrderId = payloadData.getProjectOrderId();
236	
237			// 只处理用工任务的生成消息
238			if (!IndicatorScheduleDAGService.DISPATCH_NODE_TASK_TYPES.contains(payloadData.getTaskType())
239					|| !payloadData.getChangeType().equals(1)) {
240				return;
241			}
242	
243			if (!StringUtils.isNumeric(projectOrderId)) {
244				LOGGER.info("MaterialTaskCreateHandler执行终止, projectOrderId:{}不是数字", projectOrderId);
245				return;
246			}
247	
248			// 排程新配置开关
249			Boolean isInScheduleConfig;
250			try {
251				isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(projectOrderId);
252			} catch (Exception e) {
253				LOGGER.info("MaterialTaskCreateHandler获取排程配置开关失败, projectOrderId:{}, err:", projectOrderId, e);
254				throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取配置开关失败", e);
255			}
256	
257			// 排程初始化数据白名单
258			Boolean scheduleInit = indicatorScheduleDAGService.isScheduleProject(projectOrderId);
259	
260			// 捕捉用工任务的生成, 以此进行考核计算
261			if (isInScheduleConfig || scheduleInit) {
262				List<TaskDispatchDetailSimpleDTO> details;
263				try {
264					details = edarStarlordRpc.taskDetail(TaskDispatchDetailSimpleParam.builder()
265							.taskDispatchId(payloadData.getTaskDispatchId())
266							.build());
267				} catch (RpcException e) {
268					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "获取主材任务失败", e);
269				}
270				if (details != null && !details.isEmpty()) {
271					TaskDispatchDetailSimpleDTO detail = details.get(0);
272					List<TaskDispatchDetailSimpleDTO.TaskNodeDetail> nodes = detail.getTaskNodeDetailList().stream()
273							.filter(o -> o.getRestartCount().equals(payloadData.getRestart()))
274							.collect(Collectors.toList());
275					FigureScheduleParam scheduleParam;
276					try {
277						//根据传入的消息获取基础事件、开始节点以及扩展节点
278						scheduleParam = indicatorScheduleDAGService.getBaseEventsByDispatch(projectOrderId, detail.getMaterialCode(), nodes, detail.getTaskType(), Collections.singletonList(TimeTypeEnum.CREATE_TIME.getValue()));
279					} catch (RpcException e) {
280						LOGGER.info("处理用工任务生成消息时, getBaseEvents失败, dispatchId:{}, err:", payloadData.getTaskDispatchId(), e);
281						throw new RuntimeException(e);
282					}
283					if (scheduleParam == null) {
284						LOGGER.info("未查询到需要计算的事件节点");
285						return;
286					}
287					LOGGER.info("基于用工任务生成消息开始计算, projectId:{}, startNode: {}",
288							scheduleParam.getProjectOrderId(),
289							scheduleParam.getStartNodes().stream().map(ScheduleEventNode::getUniqCode).collect(Collectors.toList()));
290					// 按照新配置计算考核, isInScheduleConfig情况下数据同步给主材任务
291					evalScheduleOrderService.calculateScheduleIndicatorByEvents(scheduleParam.getProjectOrderId(), scheduleParam.getStartNodes(), scheduleParam.getExtNodes(), isInScheduleConfig);
292				}
293			}
294		}
295	
296	}
