45			MerchantQueryPageParam pageParam = new MerchantQueryPageParam();
46			pageParam.setMerchantTypes(Lists.newArrayList(MerchantTypeEnum.HOME_DECORATION.getCode()));
47			pageParam.setMdmCodeList(Lists.newArrayList(cityCode));
48			ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(projectId);
49			List<Integer> merchantFuseModes = new ArrayList<>();
50			if (Objects.equals(ControlModelEnum.NEW.getCode(), projectOrderDto.getControlModel())) {
51				if (Objects.equals(2, projectOrderDto.getBusinessModel())) {
52					merchantFuseModes.add(2);
53					merchantFuseModes.add(3);
54				} else {
55					merchantFuseModes.add(4);
56				}
57			}
58			pageParam.setMerchantFuseModes(merchantFuseModes);
59	
60			Page<MerchantDto> res = RpcHelper.unwrap(() -> merchantApi.queryMerchantInfoOnPage(pageParam), "dispatchReceiveApi" + ".queryDispatchReceiveByMainFlowNo");
61			if (CollectionUtils.isEmpty(res.getList())) {
62				LOGGER.error("查询分公司: {}对应的店铺为空", cityCode);
63				return null;
64			}
65	
66			return res.getList().stream().filter(merchantDto -> CollectionUtils.isEmpty(merchantDto.getSpecialLabel()) || !merchantDto.getSpecialLabel().contains("ONLY_SCM")).map(MerchantDto::getMerchantId).findFirst().orElse(null);
67	
68		}
