131			for (Page<SkuInfoForAddMaterialSubentryDto> callResult : result) {
132				if (callResult == null) {
133					continue;
134				}
135				List<SkuInfoForAddMaterialSubentryDto> records = callResult.getList();
136				if (CollectionUtils.isEmpty(records)) {
137					continue;
138				}
139				all.addAll(records);
