144		public List<SkuInfoForAddMaterialSubentryDto> querySkuDetailBatch(QuerySkuForAddMaterialSubentryParam param) {
145			List<SkuInfoForAddMaterialSubentryDto> result = Lists.newArrayList();
146			param.setPageNum(1);
147			param.setPageSize(100);
148			try {
149				Page<SkuInfoForAddMaterialSubentryDto> firstPage = querySkuDetail(param);
150				result.addAll(firstPage.getList());
151				List<CompletableFuture<Page<SkuInfoForAddMaterialSubentryDto>>> futureList = Lists.newArrayList();
152				for (Integer pageNum = 2; pageNum <= firstPage.getTotalPage(); pageNum++) {
153					QuerySkuForAddMaterialSubentryParam searchParam = new QuerySkuForAddMaterialSubentryParam();
154					BeanUtils.copyProperties(param, searchParam);
155					searchParam.setPageNum(pageNum);
156					futureList.add(CompletableFuture.supplyAsync(() -> {
157						try {
158							return querySkuDetail(searchParam);
159						} catch (RpcException e) {
160							LOGGER.error("complexQuerySkuApi.querySkuForAddMaterialSubentryV2 param:{} error:", searchParam, e);
161						}
162						return new Page<>(0, 0, 0L, Lists.newArrayList());
163					}, rpcAsyncExecutor));
164				}
165				futureList.forEach (
166						future -> result.addAll(future.join().getList())
167				);
168			} catch (Exception e) {
169				LOGGER.error("querySkuDetailBatch error:", e);
170			}
171			return result;
172		}
