174		public List<OrderProductDetailBo> fillSkuInfo(List<OrderProductDetailBo> productList){
175	
176			if (CollectionUtils.isEmpty(productList)) {
177				return Lists.newArrayList();
178			}
179	
180			List<SkuInfoForAddMaterialSubentryDto> skuInfoList = Lists.newArrayList();
181			Map<Integer, List<OrderProductDetailBo>> productMerchantMap = productList.stream()
182					.collect(Collectors.groupingBy(OrderProductDetailBo::getMerchantId));
183			for (Integer merchantId : productMerchantMap.keySet()) {
184				List<Integer> skuIdList = productMerchantMap.getOrDefault(merchantId, Lists.newArrayList()).stream()
185						.map(OrderProductDetailBo::getSkuId)
186						.map(Integer::valueOf)
187						.collect(Collectors.toList());
188				if (CollectionUtils.isEmpty(skuIdList)) {
189					continue;
190				}
191				if (Objects.isNull(merchantId) || merchantId == 0) {
192					continue;
193				}
194				QuerySkuForAddMaterialSubentryParam skuDetailParam = new QuerySkuForAddMaterialSubentryParam();
195				skuDetailParam.setSkuIds(skuIdList);
196				skuDetailParam.setMerchantId(merchantId);
197				skuDetailParam.setNeedChannelPrice(0);
198				skuInfoList.addAll(querySkuDetailBatch(skuDetailParam));
199			}
200	
201			Map<String, SkuInfoForAddMaterialSubentryDto> skuInfoMap = skuInfoList.stream()
202					.collect(Collectors.toMap(
203							skuInfo -> getKey(skuInfo.getMerchantId(),skuInfo.getSkuId()),
204							Function.identity(), (o, n) -> n)
205					);
206	
207			List<OrderProductDetailBo> result = Lists.newArrayList();
208			for (OrderProductDetailBo orderProductDTO : productList) {
209	            SkuInfoForAddMaterialSubentryDto skuDetail = skuInfoMap.get(getKey(orderProductDTO.getMerchantId(), orderProductDTO.getSkuId()));
210				orderProductDTO.setSkuDetail(skuDetail);
211				result.add(orderProductDTO);
212			}
213			return result;
214		}
