216		private String getKey(Object...item){
217			return Arrays.stream(item).map(String::valueOf).collect(Collectors.joining("-"));
218		}
219	
220		public Map<String,List<SkuInfoForAddMaterialSubentryDto>> queryCombinedSubSkuInfo(List<SkuInfoForAddMaterialSubentryDto> productList) throws RpcException {
221	
222			Map<String,List<SkuInfoForAddMaterialSubentryDto>>  combinedMerchantSubSkuMap = Maps.newHashMap();
223	
224			if (CollectionUtils.isEmpty(productList)){
225				return combinedMerchantSubSkuMap;
226			}
227	
228			// 过滤出组套
229			List<SkuInfoForAddMaterialSubentryDto> combinedProductList = productList.stream()
230				.filter(e -> Objects.equals(e.getSkuType(), (int) SkuTypeEnum.COMBINED.getType()))
231				.collect(Collectors.toList());
232	
233			// 组套商品的skuId
234			List<Integer> combinedSkuIdList = combinedProductList.stream()
235				.map(SkuInfoForAddMaterialSubentryDto::getSkuId)
236				.filter(Objects::nonNull).distinct().collect(Collectors.toList());
237	
238			// 组套商品的子sku
239			Map<Integer, List<CombineSkuDetailDto>> combinedSubSkuMap = batchGetSkuDetails(combinedSkuIdList);
240	
241			// 组套按店铺分组
242			Map<Integer, List<SkuInfoForAddMaterialSubentryDto>> productMerchantMap = combinedProductList.stream()
243				.collect(Collectors.groupingBy(SkuInfoForAddMaterialSubentryDto::getMerchantId));
244	
245			for (Integer merchantId : productMerchantMap.keySet()) {
246	
247				List<SkuInfoForAddMaterialSubentryDto> combinedProductMerchantList = productMerchantMap.getOrDefault(merchantId, Lists.newArrayList());
248	
249				// 店铺下所有组套的所有子sku
250				List<Integer> subSkuIdList = combinedProductMerchantList.stream()
251					.map(e -> combinedSubSkuMap.getOrDefault(e.getSkuId(), Lists.newArrayList()))
252					.flatMap(Collection::stream).map(CombineSkuDetailDto::getSkuId).collect(Collectors.toList());
253	
254				if (CollectionUtils.isEmpty(subSkuIdList)){
255					continue;
256				}
257	
258				QuerySkuForAddMaterialSubentryParam skuDetailParam = new QuerySkuForAddMaterialSubentryParam();
259				skuDetailParam.setSkuIds(subSkuIdList);
260				skuDetailParam.setMerchantId(merchantId);
261				skuDetailParam.setNeedChannelPrice(0);
262				List<SkuInfoForAddMaterialSubentryDto> subSkuDetailList = querySkuDetailBatch(skuDetailParam);
263				Map<Integer, SkuInfoForAddMaterialSubentryDto> subSkuDetailMap = subSkuDetailList.stream().collect(Collectors.toMap(SkuInfoForAddMaterialSubentryDto::getSkuId, Function.identity(), (o, n) -> n));
264	
265				for (SkuInfoForAddMaterialSubentryDto combinedProduct : combinedProductMerchantList) {
266					List<SkuInfoForAddMaterialSubentryDto> subSkuList = Lists.newArrayList();
267					for (CombineSkuDetailDto subSku : combinedSubSkuMap.getOrDefault(combinedProduct.getSkuId(), Lists.newArrayList())) {
268						if (subSkuDetailMap.containsKey(subSku.getSkuId())){
269							subSkuList.add(subSkuDetailMap.get(subSku.getSkuId()));
270						}
271					}
272					combinedMerchantSubSkuMap.put(getKey(merchantId,combinedProduct.getSkuId()),subSkuList);
273				}
274			}
275			return combinedMerchantSubSkuMap;
276		}
277	
278	}
