44	
45	
46		// 查询工期时间(包含虚拟瓦木时间)
47		public List<ConstructionScheduleDTO> queryConstructionScheduleDetailNew(Long projectOrderId) {
48			ProjectOrderDateV2Dto virtualInfo = null;
49	        try {
50				virtualInfo = fullServiceFulfillmentRpcService.queryVirtualWoodenWorkTime(projectOrderId);
51	        } catch (RpcException e) {
52				LOGGER.error("调用fullServiceFulfillmentRpcService.queryVirtualWoodenWorkTime失败, projectOrderNo={}, err:", projectOrderId, e);
53			}
54			List<ConstructionScheduleDTO> res = constructionScheduleRpcService.queryConstructionScheduleDetailNew(projectOrderId);
55			if (virtualInfo != null && virtualInfo.getPlanWoodAcceptanceTime().after(defaultDate)) {
56				// 替换工期时间中的瓦木时间
57				for (ConstructionScheduleDTO dto : res) {
58					if (ConstructionScheduleSequenceCodeEnum.WOOD_ACCEPTANCE.getSequenceCode().equals(dto.getSequenceCode())) {
59						String virtualTime = DateUtil.format(virtualInfo.getPlanWoodAcceptanceTime(), DateUtil.DATE_FMT_2);
60						dto.setBeginDate(virtualTime.substring(0, 10));
61						dto.setEndDate(virtualTime.substring(0, 10));
62						dto.setStartTime(virtualTime);
63						dto.setEndTime(virtualTime);
64						break;
65					}
66				}
67			}
68			return res;
69		}
