20	import org.springframework.util.Assert;
21	import org.springframework.util.StringUtils;
22	
23	import java.util.*;
24	
25	@Component
26	@Slf4j
27	public class EventDrivenSubscriberV2 {
28	
29		private EventSubMapper eventSubMapper;
30	
31		private EventDispatcher eventDispatcher;
32	
33		private EventDrivenProperties eventDrivenProperties;
34	
35		private EventDrivenSubHookManager eventDrivenSubHookManager;
36	
37		private final static int MAX_DATA_LENGTH = 10240;
38	
39		@Autowired
40		public EventDrivenSubscriberV2(EventSubMapper eventSubMapper, EventDispatcher eventDispatcher
41			, EventDrivenProperties eventDrivenProperties, EventDrivenSubHookManager eventDrivenSubHookManager) {
42			this.eventSubMapper = eventSubMapper;
43			this.eventDispatcher = eventDispatcher;
44			this.eventDrivenProperties = eventDrivenProperties;
45			this.eventDrivenSubHookManager = eventDrivenSubHookManager;
46		}
47	
48		public void persistAndHandleMessage(String payload) {
49			Assert.notNull(payload, "persistAndHandleMessage businessType not Null");
50			Event event = Jacksons.readValue(payload, Event.class);
51			//不包含直接返回
52			if (!checkContainEventType(event.getEventType())) {
53				return;
54			}
55			//环境不匹配记录日志并返回，仅配置项 sameEnvLimit 为 true 有效
56			if (!checkSameEventEnv(event, eventDrivenProperties)) {
57				LOGGER.warn("reject event: {}, reason: not same env. subscriber env: {}", event, eventDrivenProperties.getServerGroup());
58				return;
59			}
60			EventSub eventSub = convertEventSub(event);
61			if (this.saveNewEvent(eventSub)) {
62				this.doSubscribeWithoutTransaction(eventSub);
63			}
64		}
65	
66	
67		private boolean saveNewEvent(EventSub eventSub) {
68			try {
69				EventSubExample eventSubExample = new EventSubExample();
70				eventSubExample.createCriteria()
71						.andEventIdEqualTo(eventSub.getEventId())
72						.andEventGroupEqualTo(eventSub.getEventGroup())
73						.andEventServiceEqualTo(eventSub.getEventService());
74				List<EventSub> eventSubs = eventSubMapper.selectByExample(eventSubExample);
75				if (CollectionUtils.isNotEmpty(eventSubs)) {
76					return false;
77				}
78				// 数据过长时截断
79				String originData = eventSub.getPayloadData();
80				if (!StringUtils.isEmpty(eventSub.getPayloadData()) && eventSub.getPayloadData().length() > MAX_DATA_LENGTH) {
81					eventSub.setPayloadData(eventSub.getPayloadData().substring(0, MAX_DATA_LENGTH));
82				}
83				int rows = eventSubMapper.insertSelective(eventSub);
84				eventSub.setPayloadData(originData);
85				return rows > 0;
86			} catch (DuplicateKeyException dke) {
87				LOGGER.warn("消息重复:, {}", JSONObject.toJSONString(eventSub), dke);
88			}
89			return false;
90		}
91	
92	
93		public void doSubscribeWithoutTransaction(EventSub eventSub) {
94			try {
95				eventDispatcher.dispatch(eventSub, true);
96				int result = this.eventSubMapper.updateEventStatusByPrimaryKeyInCasMode(eventSub.getId(), eventSub.getEventStatus(), EventStatus.DONE.getType());
97				LOGGER.info("event id {} result {} execute success.", eventSub.getEventId(), result);
98				eventDrivenSubHookManager.executeSubSuccess(eventSub);
99			} catch (Exception e) {
100				int result = this.eventSubMapper.updateEventStatusByPrimaryKeyInCasMode(eventSub.getId(), eventSub.getEventStatus(), EventStatus.ERROR.getType());
101				LOGGER.error("event id {} result {} execute error.", eventSub.getEventId(), result, e);
102				eventDrivenSubHookManager.executeSubError(eventSub, e);
103			}
104		}
105	
106		private EventSub convertEventSub(Event event) {
107			final EventSub eventSub = new EventSub();
108			eventSub.setEventId(event.getEventId());
109			eventSub.setEventType(event.getEventType());
110			eventSub.setEventOccurTime(DateUtils.parseISO8601DateTime(event.getEventOccurTime()));
111			eventSub.setEventGroup(eventDrivenProperties.getServerGroup());
112			eventSub.setEventContextKey(event.getEventContextKey());
113			String serverName = eventDrivenProperties.getServerName();
114			if (StringUtils.isEmpty(serverName) || "application".equals(serverName)) {
115				throw new IllegalArgumentException("服务名称不得为空 请设置spring.application.name属性");
116			}
117			eventSub.setEventService(serverName);
118			eventSub.setPayloadData(Jacksons.parse(event.getPayloadData()));
119			eventSub.setLockVersion(EventDrivenContent.EVENT_LOCK_VERSION);
120			eventSub.setEventStatus(EventStatus.NEW.getType());
121			return eventSub;
122		}
123	
124		private boolean checkContainEventType(String eventType) {
125			Set<String> eventTypes = eventDispatcher.getEventType();
126			return eventTypes.contains(eventType);
127		}
128	
129		private boolean checkSameEventEnv(Event event, EventDrivenProperties eventDrivenProperties) {
130			Boolean sameEnvLimit = eventDrivenProperties.getSameEnvLimit();
131			if (sameEnvLimit) {
132				Map<String, String> metadata = Optional.ofNullable(event.getMetadata()).orElse(Collections.emptyMap());
133				String eventGroup = metadata.getOrDefault("eventGroup", EventDrivenProperties.DEFAULT_EVENT_ENV);
134				return eventGroup.equals(eventDrivenProperties.getServerGroup());
135			} else {
136				return true;
137			}
138		}
139	}
